class Solution {
public:
    char getKthCharacter(RopeTreeNode* root, int k) {
        auto get_len = [](RopeTreeNode* node) {
            if (!node) return 0;
            if (node->len > 0) return node->len;
            return (int)node->val.size();
        };
        RopeTreeNode* curr = root;
        while (curr) {
            if (curr->len == 0) {
                return curr->val[k - 1];
            }
            int left_len = get_len(curr->left);
            if (k <= left_len) {
                curr = curr->left;
            } else {
                k -= left_len;
                curr = curr->right;
            }
        }
        return ' ';
    }
};

class Solution {
    public char getKthCharacter(RopeTreeNode root, int k) {
        RopeTreeNode curr = root;
        while (curr != null) {
            if (curr.len == 0) {
                return curr.val.charAt(k - 1);
            }
            int leftLen = getLen(curr.left);
            if (k <= leftLen) {
                curr = curr.left;
            } else {
                k -= leftLen;
                curr = curr.right;
            }
        }
        return ' ';
    }

    private int getLen(RopeTreeNode node) {
        if (node == null) return 0;
        if (node.len > 0) return node.len;
        return node.val.length();
    }
}

